package main

import (
	"bufio"
	"fmt"
	"io/ioutil"
	"os"
	"strings"
)

func input(readFile bool) string {
	if readFile {
		data, err := ioutil.ReadFile("sample.txt")
		if err != nil {
			panic(err)
		}
		return string(data)
	} else {
		reader := bufio.NewReader(os.Stdin)
		data, err := ioutil.ReadAll(reader)
		if err != nil {
			panic(err)
		}
		return strings.TrimRight(string(data), "\n\r")
	}
}

func solve(tokens []string) {
	s1 := tokens[0]
	s2 := tokens[1]

	p1 := 0
	for _, c := range s1 {
		if c == '+' {
			p1++
		} else {
			p1--
		}
	}

	p2 := 0
	uc := 0
	for _, c := range s2 {
		switch c {
		case '+':
			p2++
		case '-':
			p2--
		default:
			uc++
		}
	}

	v := make([]int, 0)
	for bit := 0; bit < (1 << uc); bit++ {
		p := p2
		for i := 0; i < uc; i++ {
			if (bit>>i)&1 == 1 {
				p++
			} else {
				p--
			}
		}
		v = append(v, p)
	}

	cnt := 0
	for _, x := range v {
		if x == p1 {
			cnt++
		}
	}

	fmt.Printf("%f\n", float64(cnt)/float64(len(v)))
}

func main() {
	const READ_FROM_FILE = false

	s := input(READ_FROM_FILE)
	ws := strings.Fields(s)

	solve(ws)
}

